  let state=fresh();try{const saved=JSON.parse(localStorage.getItem('moonlit-save'));if(saved&&typeof saved.essence==='number'){state={...fresh(),...saved,upgrades:{...fresh().upgrades,...saved.upgrades}}}}catch{}
  const $=id=>document.getElementById(id), fmt=n=>Math.floor(n).toLocaleString('en-US'), compact=n=>n>=1e9?(n/1e9).toFixed(2)+'b':n>=1e6?(n/1e6).toFixed(2)+'m':n>=1e4?(n/1e3).toFixed(1)+'k':fmt(n);
